function assertRows(rows){if(!Array.isArray(rows))throw Error('Base de caixa inválida; conteúdo preservado');const ids=new Set;for(const r of rows){if(!r||typeof r.id!=='string'||ids.has(r.id)||!['despesa','receita'].includes(r.tipo)||!['pendente','pago','cancelado'].includes(r.status)||!Number.isSafeInteger(r.valorCentavos)||r.valorCentavos<=0||!Array.isArray(r.rateios)||!Array.isArray(r.historico))throw Error('Registro de caixa inválido; conteúdo preservado');ids.add(r.id);date(r.data);let sum=0;const works=new Set;for(const x of r.rateios){if(!x||typeof x.obra!=='string'||!x.obra||works.has(x.obra)||!Number.isSafeInteger(x.centavos)||x.centavos<=0)throw Error('Rateio armazenado inválido; conteúdo preservado');works.add(x.obra);sum+=x.centavos;}if(r.rateios.length&&sum!==r.valorCentavos)throw Error('Rateio armazenado diverge do total');}return rows;}
function create(input,works,actor,{id=P.newId(),now=new Date().toISOString()}={}){text(actor,'responsável');if(!['despesa','receita'].includes(input.tipo)||!['pendente','pago'].includes(input.status))throw Error('Tipo ou situação inválida');if(!categories.includes(input.categoria))throw Error('Escolha uma categoria');const amount=cents(input.valor),allocations=[],seen=new Set;for(const x of input.rateios||[]){const name=text(x.obra,'obra');if(!works.includes(name)||seen.has(name))throw Error('Obra inexistente ou repetida no rateio');seen.add(name);allocations.push({obra:name,centavos:cents(x.valor),...(x.centroCusto?{centroCusto:text(x.centroCusto,'centro de custo')}: {})});}if(allocations.length&&allocations.reduce((s,x)=>s+x.centavos,0)!==amount)throw Error('A soma dos rateios precisa ser igual ao valor total');return {id,tipo:input.tipo,status:input.status,data:date(input.data),empresa:text(input.empresa,'empresa'),favorecido:text(input.favorecido,'favorecido / origem'),descricao:text(input.descricao,'descrição'),categoria:input.categoria,conta:text(input.conta,'conta / forma'),valorCentavos:amount,rateios:allocations,...(input.contaId?{contaId:input.contaId}:{}),...(input.vencimento?{vencimento:date(input.vencimento)}:{}),pagoEm:input.status==='pago'?date(input.pagoEm):null,criadoEm:now,criadoPor:actor,historico:[{acao:'criado',em:now,por:actor}]};}
function append(rows,entry){assertRows(rows);assertRows([entry]);if(rows.some(r=>r.id===entry.id))throw Error('Lançamento já registrado');return [...structuredClone(rows),structuredClone(entry)];}
function transition(rows,id,status,actor,{reason='',paidDate='',now=new Date().toISOString()}={}){assertRows(rows);text(actor,'responsável');const clone=structuredClone(rows),r=clone.find(x=>x.id===id);if(!r)throw Error('Lançamento não encontrado');if(!['pago','cancelado'].includes(status))throw Error('Situação não permitida');if(r.status===status)return clone;if(status==='cancelado'&&r.rhFechamentoId)throw Error('Lançamento vinculado a fechamento de RH; use o estorno pelo módulo de Remuneração.');if(r.status==='cancelado')throw Error('Lançamento cancelado é mantido para consulta');if(status==='pago'&&r.status!=='pendente')throw Error('Pagamento já registrado');const motive=status==='cancelado'?text(reason,'motivo do cancelamento'):'';r.historico.push({acao:status,de:r.status,em:now,por:actor,motivo:motive});r.status=status;if(status==='pago')r.pagoEm=date(paidDate);return clone;}
function report(rows,{obra='',empresa='',categoria='',from='',to='',tipo='despesa',centroCusto='',favorecido=''}={}){assertRows(rows);if(from)date(from);if(to)date(to);if(from&&to&&from>to)throw Error('Data inicial posterior à final');const result={rows:[],pago:0,pendente:0,cancelado:0,empresas:new Map,categorias:new Map};for(const r of rows){if(favorecido&&!String(r.favorecido).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').includes(String(favorecido).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').trim()))continue;if(r.tipo!==tipo||empresa&&r.empresa!==empresa||categoria&&r.categoria!==categoria||from&&r.data<from||to&&r.data>to)continue;const portions=r.rateios.filter(x=>(!obra||x.obra===obra)&&(!centroCusto||(x.centroCusto||'Sem centro de custo (anterior)')===centroCusto));const amount=(obra||centroCusto)?portions.reduce((s,x)=>s+x.centavos,0):r.valorCentavos;if(!amount)continue;result.rows.push({...structuredClone(r),valorExibido:amount});result[r.status]+=amount;if(r.status!=='cancelado'){result.empresas.set(r.empresa,(result.empresas.get(r.empresa)||0)+amount);result.categorias.set(r.categoria,(result.categorias.get(r.categoria)||0)+amount);}}result.rows.sort((a,b)=>b.data.localeCompare(a.data)||a.id.localeCompare(b.id));return result;}
function csv(report){const cell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const rows=[['ID','Data do lançamento','Empresa','Favorecido / origem','Categoria','Descrição','Situação','Valor no filtro (R$)','Valor total (R$)','Pago / recebido em','Conta / forma','Rateios / centros de custo','Vencimento'],...report.rows.map(r=>[r.id,r.data.split('-').reverse().join('/'),r.empresa,r.favorecido,r.categoria,r.descricao,r.status,(r.valorExibido/100).toFixed(2).replace('.',','),(r.valorCentavos/100).toFixed(2).replace('.',','),r.pagoEm||'',r.conta,r.rateios.map(x=>x.obra+' / '+(x.centroCusto||'Sem centro de custo (anterior)')+': '+(x.centavos/100).toFixed(2)).join(' | '),r.vencimento||''])];return '\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n');}
